// scripts/tests/render-test-sup-consumers.js
// REVISION 2026-11-24a — first version.
//
// Chromium render test for the four `sup` consumers in index.html, network
// stubbed. Asserts that a superseded fixture is excluded from segments, bands,
// counts and "still to play", and SHOWN greyed with the id of the game that
// replaced it, in: the grading panel's team card, the game sheet, the club week
// row, and the team card's Fixtures tab (which reads team-stats, not games/bv).
//
// ⚠ THE FIXTURES ARE THE REAL build-team-stats.js OUTPUT, regenerated by
// scripts/tests/make-sup-fixtures.js. The UI is therefore tested against what the
// builder actually writes rather than against a hand-written idea of it (T103: a
// fixture written from the same belief as the code tests the belief).
//
// ⚠ NEEDS PLAYWRIGHT, and index.html — which lives in the markjovic/stattrack
// repo, not this one. It runs from the combined working folder where both sit
// side by side. Where index.html is not present it SKIPS with a message and exits
// 0 rather than failing: a test that cannot see its subject has not passed.
//
// Run:  node scripts/tests/render-test-sup-consumers.js

'use strict';
const path = require('path');
const fs   = require('fs');

const ROOT    = path.join(__dirname, '..', '..');
const INDEX   = path.join(ROOT, 'index.html');
const FIXTURES= path.join(__dirname, 'fixtures');
if (!fs.existsSync(INDEX)) {
  console.log('SKIPPED — index.html is not beside this checkout (it lives in markjovic/stattrack).');
  console.log('          Expected at: ' + INDEX);
  process.exit(0);
}
let chromium;
try { ({ chromium } = require('playwright')); }
catch (_) { console.log('SKIPPED — playwright is not installed in this environment.'); process.exit(0); }
const http = require('http');

const SID = 'tst00001';
const games = JSON.parse(fs.readFileSync(path.join(FIXTURES, 'games-bv-sup.json'), 'utf8'));
const ts    = JSON.parse(fs.readFileSync(path.join(FIXTURES, 'team-stats-bv-sup.json'), 'utf8'));
const idx   = { seasons: { [SID]: { id: SID, name: 'Test Season', fullName: 'Test Season', compName: 'Test',
  compId: 'c1', orgName: 'Test Org', orgId: 'o1', startDate: '2026-10-01', endDate: '2027-03-01', locked: false,
  grades: [{ id: 'GR_A', name: 'Friday U11 Boys A', age: 'Under 11', gender: 'Boys' },
           { id: 'GR_AR', name: 'Friday U11 Boys AR', age: 'Under 11', gender: 'Boys' }] } } };

let pass = 0, fail = 0;
const ok = (c, l, d) => { if (c) { pass++; console.log('  ok   ' + l); } else { fail++; console.log('  FAIL ' + l + (d !== undefined ? '  -> ' + d : '')); } };
const eq = (a, b, l) => ok(a === b, l, `got ${JSON.stringify(a)}, expected ${JSON.stringify(b)}`);

(async () => {
  const srv = http.createServer((req, res) => {
    res.writeHead(200, { 'Content-Type': 'text/html' });
    res.end(fs.readFileSync(INDEX));
  }).listen(0);
  const port = srv.address().port;

  const browser = await chromium.launch();
  const page = await browser.newPage();
  const errors = [];
  page.on('console', m => { if (m.type() === 'error') errors.push(m.text()); });
  page.on('pageerror', e => errors.push('pageerror: ' + e.message));

  await page.route('**/*', route => {
    const u = route.request().url();
    const json = (o) => route.fulfill({ status: 200, contentType: 'application/json', body: JSON.stringify(o) });
    if (u.includes(`/games/bv/${SID}.json`))      return json(games);
    if (u.includes(`/team-stats/bv/${SID}.json`)) return json(ts);
    if (u.includes('/data/sports-index.json'))    return json(idx);
    if (u.includes('/data/venue-index.json'))     return json([]);
    if (u.includes('/data/team-index.json'))      return json({});
    if (u.startsWith(`http://localhost:${port}`)) return route.continue();
    return route.fulfill({ status: 404, contentType: 'application/json', body: 'null' });
  });

  await page.goto(`http://localhost:${port}/index.html`, { waitUntil: 'networkidle' });

  // ── the model ──────────────────────────────────────────────────────────────
  const model = await page.evaluate(async (sid) => {
    const M = await grBuild(sid);
    const t = M.teams.get('TEAM1');
    return {
      apps: t.apps.map(a => a.key), sups: (t.sups || []).map(a => a.key), superseded: t.superseded,
      segs: t.segs.map(s => s.grade), conflict: t.conflict,
      appsHaveSup: t.apps.some(a => a.sup),
    };
  }, SID);
  ok(!model.apps.includes('g_sup'), 'the superseded fixture is OUT of t.apps');
  eq(model.sups.join(','), 'g_sup', 't.sups holds exactly the superseded fixture');
  eq(model.superseded, 1, 't.superseded counts it');
  ok(!model.appsHaveSup, 'nothing left in apps carries a sup flag');
  eq(model.segs.join(' -> '), 'Friday U11 Boys A', 'segments show ONE grade - no phantom move into the superseded grade');
  eq(model.conflict, null, 'no conflict is raised: the remaining fixture agrees with the played grade');

  // ── the team card ──────────────────────────────────────────────────────────
  const card = await page.evaluate(async (sid) => {
    // #gr-team only exists once the panel has rendered, so open it the way the
    // deep link does rather than poking GRCUR.
    const M = await grBuild(sid);
    const key = M.groups[0].key;   // groups is an ARRAY of {key,label,teams,...}
    grOpen(sid, key, false);
    grTeamCard('TEAM1');
    const box = document.getElementById('gr-team');
    const rec = box.querySelector('.gr-rec').textContent;
    const rows = [...box.querySelectorAll('tbody tr')].map(tr => ({
      cls: tr.className, onclick: tr.getAttribute('onclick') || '',
      cells: [...tr.querySelectorAll('td')].map(td => td.textContent.trim()),
    }));
    return { rec, rows };
  }, SID);
  ok(/2W 0L over 2 played/.test(card.rec), 'record counts only the two played games', card.rec);
  ok(/1 still to play/.test(card.rec), '"still to play" is 1 - the real future fixture, not 2', card.rec);
  ok(/1 regraded, struck through above their replacements and not counted/.test(card.rec),
     'the cancelled one is declared, not silently dropped', card.rec);
  eq(card.rows.length, 4, 'all four fixtures are rows - nothing hidden');
  const supIdx = card.rows.findIndex(r => r.cells.some(c => c.includes('RGRD')));
  const supRow = supIdx < 0 ? null : card.rows[supIdx];
  ok(!!supRow, 'the cancelled fixture renders with an RGRD chip');
  ok(supRow && /\u2193 RGRD/.test(supRow.cells.join(' ')),
     'and carries the down arrow, because its replacement IS in this list', supRow && supRow.cells.join(' '));
  ok(supRow && /sup-row/.test(supRow.cls), 'and carries the greyed, struck-through row class');
  ok(supRow && /openSheet\('g_played'/.test(supRow.onclick), 'clicking it opens the game that REPLACED it', supRow && supRow.onclick);
  const playedIdx = card.rows.findIndex(r => r.onclick.includes("openSheet('g_played'") && !r.cells.some(c => c.includes('RGRD')));
  const playedRow = playedIdx < 0 ? null : card.rows[playedIdx];
  ok(!!playedRow, 'the played game still opens its own box score');
  // \u2193 THE ORDERING IS THE POINT. The cancelled fixture must sit DIRECTLY above
  // the game that replaced it, whatever the date sort would have done with two
  // rows carrying the same date.
  eq(playedIdx - supIdx, 1, 'the cancelled fixture is the row immediately ABOVE its replacement',
     `sup at ${supIdx}, played at ${playedIdx}`);

  // ── renderMode and the game sheet ──────────────────────────────────────────
  const modes = await page.evaluate(() => ({
    sup: renderMode({ st: 'UPCOMING', sup: 'g_played' }),
    up:  renderMode({ st: 'UPCOMING' }),
    scored: renderMode({ st: 'UPCOMING', sup: 'g_played', hs: 10, as: 9 }),
    empty: renderMode({ st: 'UPCOMING', sup: '' }),
  }));
  eq(modes.sup, 'superseded', 'renderMode calls a flagged fixture superseded');
  eq(modes.up, 'upcoming', 'a genuine upcoming fixture is unchanged');
  eq(modes.scored, 'normal', 'a scored game beats a stale flag - the score is the honest answer');
  eq(modes.empty, 'upcoming', 'an empty sup string is not a flag');

  const sheet = await page.evaluate(async (sid) => {
    await openSheet('g_sup', sid);
    const b = document.getElementById('sh-body');
    return { html: b.innerHTML, text: b.textContent };
  }, SID);
  ok(/bdg bSUP/.test(sheet.html), 'the game sheet badges it as superseded');
  ok(/openSheet\('g_played'/.test(sheet.html), 'and the badge opens the replacing game');
  ok(!/Upcoming/.test(sheet.text), 'the sheet no longer says "Upcoming" for a date in the past', sheet.text.slice(0, 120));

  // ── club week row ──────────────────────────────────────────────────────────
  const crow = await page.evaluate((g) => {
    const mk = (gm, gid) => clubRowHTML({ g: gm, gid, sid: 'tst00001', hMine: true, aMine: false, hn: gm.hn, an: gm.an });
    return { sup: mk(g.games.g_sup, 'g_sup'), up: mk(g.games.g_future, 'g_future'), played: mk(g.games.g_played, 'g_played') };
  }, games);
  ok(/bdg bSUP/.test(crow.sup) && /sup-row/.test(crow.sup), 'club week renders a cancelled fixture greyed with the chip');
  ok(/RGRD/.test(crow.sup), 'club week uses the RGRD label too');
  ok(!/\u2193/.test(crow.sup),
     'and NO down arrow - the club week view is one week across clubs, so the replacement is not reliably the next row');
  ok(/data-sup="g_played"/.test(crow.sup), 'and carries the replacing id for the click handler');
  ok(!/bSUP/.test(crow.up) && !/sup-row/.test(crow.up), 'a genuine future fixture is untouched');
  ok(/g-res rW/.test(crow.played), 'a played game still renders its result');

  // ── team card fixture rows (team-stats path) ───────────────────────────────
  const fx = await page.evaluate(async (sid) => {
    await loadTeam('TEAM1', sid);
    const rows = [...document.querySelectorAll('.frow')].map(r => ({
      gid: r.dataset.gid, sup: r.dataset.sup || '', result: r.dataset.result || '',
      cls: r.className, txt: r.textContent.replace(/\s+/g, ' ').trim(),
    }));
    return rows;
  }, SID);
  eq(fx.length, 4, 'the Fixtures tab lists all four');
  const fsup = fx.find(r => r.gid === 'g_sup');
  eq(fsup && fsup.sup, 'g_played', 'the superseded row carries data-sup from team-stats');
  ok(fsup && /sup-row/.test(fsup.cls), 'and the greyed class');
  ok(fsup && /RGRD/.test(fsup.txt), 'and shows the chip rather than an em dash');
  const fsupIdx = fx.findIndex(r => r.gid === 'g_sup');
  const fplayedIdx = fx.findIndex(r => r.gid === 'g_played');
  eq(fplayedIdx - fsupIdx, 1, 'Fixtures tab also puts the cancelled row immediately above its replacement',
     `sup at ${fsupIdx}, played at ${fplayedIdx}`);
  ok(fsup && /\u2193 RGRD/.test(fsup.txt), 'and the down arrow, since the replacement is in this list');
  const ffut = fx.find(r => r.gid === 'g_future');
  ok(ffut && !ffut.sup && !/sup-row/.test(ffut.cls), 'the real future fixture is untouched');

  eq(errors.length, 0, 'zero console errors', errors.slice(0, 3).join(' | '));

  await browser.close();
  srv.close();
  console.log(`\n  ${pass} passed, ${fail} failed`);
  process.exit(fail ? 1 : 0);
})().catch(e => { console.error('HARNESS FAILURE:', e); process.exit(2); });
